package com.eduflow.service;
import com.eduflow.dto.PortalDtos.AuditResponse; import com.eduflow.entity.*; import com.eduflow.exception.EduFlowException; import com.eduflow.repository.*; import com.eduflow.security.TenantRlsContext; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.time.Instant; import org.springframework.data.domain.PageRequest;
@Service @RequiredArgsConstructor
public class AuditLogService {
 private final CenterRepository centers; private final UserRepository users; private final AuditLogRepository logs; private final TenantRlsContext tenantRls;
 @Transactional public void record(Long centerId,Long actorId,String action,String type,Long entityId,String details){apply(centerId);User actor=actorId==null?null:users.findById(actorId).orElse(null);logs.save(new AuditLog(centers.getReferenceById(centerId),actor,action,type,entityId,details));}
 @Transactional(readOnly=true) public List<AuditResponse> list(Long centerId,String action,String entityType,Long actorUserId,Instant from,Instant to){apply(centerId);if(from!=null&&to!=null&&!from.isBefore(to))throw new EduFlowException(HttpStatus.BAD_REQUEST,"audit.invalid-date-range");String safeAction=blankToNull(action);String safeEntity=blankToNull(entityType);return logs.searchByCenter(centerId,safeAction,safeEntity,actorUserId,from,to,PageRequest.of(0,200)).stream().map(l->new AuditResponse(l.getId(),l.getActor()==null?null:l.getActor().getId(),l.getAction(),l.getEntityType(),l.getEntityId(),l.getDetails(),l.getCreatedAt())).toList();}
 private String blankToNull(String value){return value==null||value.isBlank()?null:value.trim();}
 private void apply(Long id){if(id==null)throw new EduFlowException(HttpStatus.BAD_REQUEST,"tenant.context.required");Center c=centers.findById(id).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"center.not-found"));if(c.getStatus()!=CenterStatus.ACTIVE)throw new EduFlowException(HttpStatus.FORBIDDEN,"tenant.center.inactive");tenantRls.apply(id);}
}
